/* Rest belongs to its preceding set, so it never becomes an extra approach. */
function setRestSeconds(s){return Number.isFinite(s?.restSeconds)&&s.restSeconds>0?Math.min(3600,Math.round(s.restSeconds)):null}
function renderSetRest(s,ei,si,name){const seconds=setRestSeconds(s);if(seconds==null)return '';const t=matchingCountdown('rest',ei,si),remaining=t?countdownRemaining(t):s.restDone?0:seconds,fields=isTimed({id:state.active.exercises[ei].id})&&!hasDistance(exercise(state.active.exercises[ei].id))?1:2;return swipeSetRow('rest',ei,si,`<div class="set-rest ${t?'has-countdown':''}" data-rest-row="${ei},${si}" style="--set-fields:${fields};--rest-progress:${t?countdownProgress(t):s.restDone?100:0}"><span class="rest-progress-track" aria-hidden="true"><span class="rest-progress"></span></span><span class="rest-label">Перерыв</span><label class="set-metric"><input type="text" inputmode="text" value="${countdownTime(remaining)}" ${t&&!t.finished?'readonly':''} data-rest-duration="${ei},${si}" aria-label="Перерыв после подхода ${si+1}: ${esc(name)}, секунды"><span class="set-unit">${t?'из '+countdownTime(seconds):'м:с'}</span></label>${countdownButton('rest',ei,si,name)}<button class="done rest-done ${s.restDone||t?.finished?'selected':''}" data-action="finish-rest" data-ei="${ei}" data-si="${si}" aria-label="Завершить перерыв после подхода ${si+1}: ${esc(name)}" aria-pressed="${!!s.restDone||!!t?.finished}">${icon('check')}</button></div>`)}
function renderReadRest(s){const seconds=setRestSeconds(s);return seconds==null?'':`<div class="read-rest">${icon('timer')}<span>Перерыв</span><b>${durationText(seconds)}</b></div>`}
function addSetRest(ei){const e=state.active?.exercises[ei],si=(e?.sets.length||0)-1;if(si<0)return null;if(setRestSeconds(e.sets[si])==null){e.sets[si].restSeconds=60;persist()}return [ei,si]}
function editSetRest(ei,si,value){const s=state.active?.exercises[ei]?.sets[si],n=parseSetTime(value);if(!s||String(value).trim()===''||!Number.isInteger(n)||n<1||n>3600)return false;s.restSeconds=n;s.restDone=false;if(matchingCountdown('rest',ei,si))state.active.countdown=null;persist();return true}
function removeSetRest(ei,si){const s=state.active?.exercises[ei]?.sets[si];if(!s)return;delete s.restSeconds;delete s.restDone;if(matchingCountdown('rest',ei,si))state.active.countdown=null;persist()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||!['add-rest','remove-rest'].includes(b.dataset.action))return;e.preventDefault();e.stopImmediatePropagation();const ei=Number(b.dataset.ei);if(b.dataset.action==='add-rest'){const target=addSetRest(ei);if(!target)return;render();document.querySelector(`[data-rest-duration="${target.join(',')}"]`)?.focus()}else{removeSetRest(ei,Number(b.dataset.si));render()}},true);

document.addEventListener('change',e=>{const input=e.target;if(!input.hasAttribute('data-rest-duration'))return;const [ei,si]=input.dataset.restDuration.split(',').map(Number);if(!editSetRest(ei,si,input.value)){input.value=countdownTime(setRestSeconds(state.active?.exercises[ei]?.sets[si])||60);toast('Перерыв — от 1 до 3600 секунд')}});
